  void loadFollowedArtists() {
    auto path = KuroAudio::getTracksDirectory() / "followed_artists.json";
    std::error_code ec;
    if (!std::filesystem::exists(path, ec)) {
      // Se o arquivo nao existir, inicializa com os artistas padrao
      followed_artists = {"JOX (BR)", "Astrix", "Aura Vortex", "Blazy"};
      saveFollowedArtists();
      return;
    }
    std::ifstream f(path);
    if (!f.is_open())
      return;
    std::string text((std::istreambuf_iterator<char>(f)),
                     std::istreambuf_iterator<char>());
    followed_artists.clear();
    size_t pos = 0;
    while ((pos = text.find('"', pos)) != std::string::npos) {
      size_t vend = text.find('"', pos + 1);
      if (vend == std::string::npos)
        break;
      std::string item = text.substr(pos + 1, vend - pos - 1);
      pos = vend + 1;
      if (!item.empty() && item != "artists" && item != "[" && item != "]" &&
          item != ",") {
        if (std::find(followed_artists.begin(), followed_artists.end(), item) ==
            followed_artists.end()) {
          followed_artists.push_back(item);
        }
      }
    }
  }

  void saveFollowedArtists() {
    auto path = KuroAudio::getTracksDirectory() / "followed_artists.json";
    std::ofstream f(path);
    if (!f.is_open())
      return;
    f << "[\n";
    for (size_t i = 0; i < followed_artists.size(); i++) {
      f << "  \"" << followed_artists[i] << "\"";
      if (i + 1 < followed_artists.size())
        f << ",";
      f << "\n";
    }
    f << "]\n";
  }

  void openSourceMatrix(const KuroAudio::SpotifyDJTrack &trk) {
    show_search_modal = true;
    search_modal_view = 0;
    cloud_hub_active_tab = 0;
    selected_source_track_id = trk.id;
    selected_source_track_title = trk.title;
    selected_source_track_artist = trk.artist;
    selected_source_track_album = trk.album;
    selected_source_track_bpm = trk.bpm;
    selected_source_track_key = trk.key;
    selected_source_track_subgenre = trk.subgenre;
    selected_source_track_dur = trk.duration_sec;
    selected_source_track_art_url = trk.artwork_url;
    selected_source_track_rgba = trk.local_rgba_path;
    selected_source_track_tex = trk.gl_tex_id;
    if (selected_source_track_tex == 0 && !trk.local_rgba_path.empty()) {
      selected_source_track_tex =
          KuroAudio::SpotifyDJService::UploadRGBATexture(trk.local_rgba_path);
    }
    loadFollowedArtists();
    is_following_selected_artist = false;
    for (const auto &a : followed_artists) {
      if (a == trk.artist) {
        is_following_selected_artist = true;
        break;
      }
    }
    spotify_service.searchSourcesAsync(trk.id, trk.title, trk.artist);
  }

