  void scanUSBTracks(const std::string &drive_root) {
    usb_scanned_tracks.clear();
    try {
      std::filesystem::path root(drive_root);
      if (!std::filesystem::exists(root))
        return;
      std::vector<std::filesystem::path> search_paths = {
          root, root / "Music", root / "Tracks", root / "PIONEER" / "Contents"};
      for (const auto &sp : search_paths) {
        if (!std::filesystem::exists(sp))
          continue;
        for (const auto &entry : std::filesystem::directory_iterator(sp)) {
          if (entry.is_regular_file()) {
            auto ext = entry.path().extension().string();
            std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
            if (ext == ".wav" || ext == ".mp3" || ext == ".flac" ||
                ext == ".aiff" || ext == ".m4a") {
              KuroAudio::DJLibraryTrack trk;
              std::string fn = entry.path().stem().string();
              trk.id = "usb_" + std::to_string(std::hash<std::string>{}(
                                    entry.path().string()));
              size_t sep = fn.find(" - ");
              if (sep != std::string::npos) {
                trk.artist = fn.substr(0, sep);
                trk.title = fn.substr(sep + 3);
              } else {
                trk.artist = "Pen Drive USB";
                trk.title = fn;
              }
              trk.local_wav_path = entry.path().string();
              trk.bpm = 138.0;
              trk.key = "8A / Am";
              trk.subgenre = "USB / Removable";
              trk.is_downloaded = true;
              usb_scanned_tracks.push_back(trk);
              if (usb_scanned_tracks.size() >= 300)
                break;
            }
          }
        }
      }
    } catch (...) {
    }
  }
  int rekordbox_pad_mode[4] = {0, 0, 0,
                               0}; // 0 = HOT CUE, 1 = BEAT LOOP, 2 = PAD FX 1,
                                   // 3 = SAMPLER, 4 = STEMS, 5 = BEAT JUMP

  void setPadMode(int deck_idx, int mode, KuroAudio::DJEngine &engine) {
    if (deck_idx < 0 || deck_idx >= 4)
      return;
    mode = std::clamp(mode, 0, 6);
    rekordbox_pad_mode[deck_idx] = mode;
    engine.decks[deck_idx].pad_mode = mode;
    ddj_hardware.setControllerPadMode(deck_idx, mode);
  }
