  int rekordbox_fx2_type = 0;
  float rekordbox_fx1_param = 0.5f;
  float rekordbox_fx2_param = 0.5f;
  float rekordbox_cfx_param = 0.5f;
  bool rekordbox_fx1_ch[6] = {false, true, false, false, false, false};
  bool rekordbox_fx2_ch[6] = {false, false, false, false, true, false};
  int rekordbox_fx1_beat_idx = 3; // 0=1/4, 1=1/2, 2=3/4, 3=1, 4=2, 5=4
  int rekordbox_fx2_beat_idx = 3;
  int rekordbox_cfx_type =
      0; // 0=FILTER, 1=SPACE, 2=DUB ECHO, 3=SWEEP, 4=NOISE, 5=CRUSH
  bool rekordbox_cfx_ch[6] = {true, false, true,
                              true, false, true}; // S, 3, 1, 2, 4, M
  float last_eq_hi[4] = {1.0f, 1.0f, 1.0f, 1.0f};
