                    if (ImGui::Button(ICON_FA_FORWARD_STEP "##DDNext", ImVec2(trans_btn_sz, trans_btn_sz))) {}
                    ImGui::SameLine(0, KuroUI::UIScaleManager::Scale(6.0f));

