                    rdl->AddCircleFilled(ImVec2(th_cx, th_cy), th_sz * 0.35f, IM_COL32(230, 80, 50, 180), 20);
                    rdl->AddCircleFilled(ImVec2(th_cx, th_cy), KuroUI::UIScaleManager::Scale(3.0f), IM_COL32(10, 14, 20, 255), 12);

