                ImGui::TextUnformatted(hero_title.c_str());
                ImGui::PopStyleColor();

                ImGui::SetCursorScreenPos(ImVec2(info_x, hero_p.y + 38.0f));
                ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.0f, 0.92f, 1.0f, 1.0f));
