                            float item_w = ImGui::GetContentRegionAvail().x;
                            float item_h = 120.0f;
                            ImVec2 item_p = ImGui::GetCursorScreenPos();
                            ImGui::Dummy(ImVec2(item_w, item_h));

                            bool is_golden = (m.play_count > 0 || m.match_badge.find("OURO") != std::string::npos);
